window.AFFIXES = {"entries": [{"id": "visi-ata", "zh": "伤害", "en": "Damage", "whole": false, "prefix": {"frag": "Visi", "cut": "[vīs](+i)", "word": "vīs", "lang": "拉丁语", "gloss": "力量", "rating": "2", "links": [{"label": "vis", "url": "https://en.wiktionary.org/wiki/vis#Latin"}, {"label": "Magnum Force", "url": "https://wiki.warframe.com/w/Magnum_Force"}, {"label": "force → vis", "url": "https://glosbe.com/en/la/force"}], "why": "vīs 是「力量」，伤害就是力量。手枪伤害 mod Magnum Force（重装火力）的 force 也是「力量」。", "whyEn": "vīs means \"force\", and damage is force. The pistol damage mod Magnum Force says the same word: force."}, "suffix": {"frag": "ata", "cut": "-{ata}", "word": "-ata", "lang": "意大利语", "gloss": "一击", "rating": "2", "links": [{"label": "-ata", "url": "https://en.wiktionary.org/wiki/-ata#Italian"}, {"label": "fucilata", "url": "https://en.wiktionary.org/wiki/fucilata#Italian"}, {"label": "coltellata", "url": "https://www.treccani.it/vocabolario/coltellata/"}, {"label": "Hornet Strike", "url": "https://wiki.warframe.com/w/Hornet_Strike"}, {"label": "Spoiled Strike", "url": "https://wiki.warframe.com/w/Spoiled_Strike"}], "why": "-ata 加在一样东西后面，意思是「用它打一下」：fucile 是步枪，fucilata 就是「一枪」；coltello 是刀，coltellata 就是「一刀」，Treccani 词典的释义是 Colpo o ferita di coltello（刀的一击，或刀留下的伤口）。伤害说的就是每一枪、每一刀打得有多重。同属性的 mod 也这么起名：手枪伤害 mod Hornet Strike（黄蜂螫刺）、近战伤害 mod Spoiled Strike（腐坏打击）都用 strike「一击」，西班牙语版叫 Golpe de avispa、Golpe podrido，golpe 也是「一击」。和 Visi 的「力量」连起来，就是「一击的力量」。", "whyEn": "Italian -ata on a noun means \"a blow with it\": fucile is a rifle, so fucilata is a gunshot; coltello is a knife, so coltellata is a stab, which Treccani defines as \"Colpo o ferita di coltello\" (a blow or wound from a knife). Damage is how hard each shot or swing hits. The same-stat mods are named the same way: the pistol damage mod Hornet Strike and the melee damage mod Spoiled Strike both say strike, and their Spanish names, Golpe de avispa and Golpe podrido, use golpe, \"a blow\". Together with Visi: the force of a blow."}, "status": "active"}, {"id": "crita-cron", "zh": "暴击几率", "en": "Critical Chance", "whole": false, "prefix": {"frag": "Crita", "cut": "[crit]ical(+a)", "word": "critical", "lang": "英语", "gloss": "暴击", "rating": "3", "links": [{"label": "critical", "url": "https://en.wiktionary.org/wiki/critical#English"}, {"label": "Critical Delay", "url": "https://wiki.warframe.com/w/Critical_Delay"}], "why": "直接取 critical（暴击）的开头。暴击 mod 里也有叫 Critical Delay（关键延迟）的。", "whyEn": "The start of critical. There is even a crit mod called Critical Delay."}, "suffix": {"frag": "cron", "cut": "mu{crōn}em", "word": "mucrō", "lang": "拉丁语", "gloss": "剑尖", "rating": "1", "links": [{"label": "mucro", "url": "https://en.wiktionary.org/wiki/mucro#Latin"}, {"label": "True Steel", "url": "https://wiki.warframe.com/w/True_Steel"}, {"label": "Tempered Blade", "url": "https://wiki.warframe.com/w/Tempered_Blade"}, {"label": "sword point → mucro", "url": "https://glosbe.com/en/la/sword%20point"}], "why": "mucrō 是「剑尖、锋刃」，变格时是 mucrōnem，中间正好有 cron。近战暴击几率 mod 的名字多和刀有关：True Steel（斩铁）的 steel 在英语里也指刀剑，曲翼近战的 Tempered Blade（强化刀片），blade 就是「刀刃」。", "alts": [], "whyEn": "mucrō means \"sword point, blade edge\", and its inflected form mucrōnem has cron right inside. Melee crit chance mods are mostly named after blades: True Steel (steel can also mean a sword) and the arch-melee Tempered Blade."}, "status": "active"}, {"id": "acri-tis", "zh": "暴击伤害", "en": "Critical Damage", "whole": true, "prefix": {"frag": "Acri", "cut": "[ācri]tā{tis}", "word": "ācritātis", "lang": "拉丁语", "gloss": "锋利", "rating": "3", "links": [{"label": "acritas", "url": "https://en.wiktionary.org/wiki/acritas#Latin"}, {"label": "Sharpened Bullets", "url": "https://wiki.warframe.com/w/Sharpened_Bullets"}, {"label": "Bladed Rounds", "url": "https://wiki.warframe.com/w/Bladed_Rounds"}, {"label": "sharpness → acritas", "url": "https://glosbe.com/en/la/sharpness"}], "why": "ācritās 是「锋利」，变格形式 ācritātis 首尾各取一段。暴伤 mod 就叫 Sharpened Bullets（尖锐子弹）、Bladed Rounds（尖刃弹头），都是「锋利」。", "whyEn": "ācritās means \"sharpness\"; its inflected form ācritātis gives both halves, head and tail. The crit damage mods are Sharpened Bullets and Bladed Rounds: sharpness again."}, "suffix": {"frag": "tis", "rating": "3", "links": []}, "status": "active"}, {"id": "sati-can", "zh": "多重射击", "en": "Multishot", "whole": false, "prefix": {"frag": "Sati", "cut": "[sati]ō", "word": "satiō", "lang": "拉丁语", "gloss": "播种", "rating": "2", "links": [{"label": "satio", "url": "https://en.wiktionary.org/wiki/satio#Latin"}, {"label": "Barrel Diffusion", "url": "https://wiki.warframe.com/w/Barrel_Diffusion"}, {"label": "Scattered Justice", "url": "https://wiki.warframe.com/w/Scattered_Justice"}, {"label": "розсіяти（乌克兰语：播种、撒开）", "url": "https://en.wiktionary.org/wiki/%D1%80%D0%BE%D0%B7%D1%81%D1%96%D1%8F%D1%82%D0%B8#Ukrainian", "labelEn": "розсіяти (Ukrainian: to sow, scatter)"}, {"label": "sowing → satio", "url": "https://glosbe.com/en/la/sowing"}], "why": "satiō 是「播种」，一把种子撒出去，就像一枪打出好几颗弹丸。多重 mod 叫 Barrel Diffusion（弹头扩散）、Scattered Justice（散射正义）；散射正义的乌克兰语名 Розсіяне правосуддя 里，「散开」本义就是「大面积播种」。", "whyEn": "satiō means \"sowing\": one throw scatters a handful of seeds, like one shot firing several pellets. The multishot mods are Barrel Diffusion and Scattered Justice. In the Ukrainian client Scattered Justice is Розсіяне правосуддя, and the first meaning of that \"scatter\" verb is \"to sow widely\"."}, "suffix": {"frag": "can", "cut": "{can}ister", "word": "canister", "lang": "英语", "gloss": "霰弹罐", "rating": "1", "links": [{"label": "canister", "url": "https://en.wiktionary.org/wiki/canister#English"}], "why": "canister 除了「罐」，还专指一种炮弹「霰弹筒」（canister shot），一筒装满弹丸，一炮打出去散成一片，就像一枪打出好几颗。", "alts": [{"word": "canon / cañón", "lang": "法语、西班牙语", "cut": "{can}on", "gloss": "枪管", "why": "canon（法语）、cañón（西班牙语）都是「枪管」：手枪多重 mod Barrel Diffusion 的法语名就是 Canon à Diffusion，西语名是 Difusión de cañón。", "links": [{"label": "cañón", "url": "https://en.wiktionary.org/wiki/cañón#Spanish"}, {"label": "Barrel Diffusion", "url": "https://wiki.warframe.com/w/Barrel_Diffusion"}, {"label": "gun barrel → cañón", "url": "https://glosbe.com/en/es/gun%20barrel"}], "whyEn": "French canon and Spanish cañón both mean \"gun barrel\": the pistol multishot mod Barrel Diffusion is Canon à Diffusion in French and Difusión de cañón in Spanish."}], "whyEn": "Besides \"can\", canister is a kind of artillery round, canister shot: a can full of balls that spreads out when fired, like one shot firing several pellets."}, "status": "active"}, {"id": "croni-dra", "zh": "射速", "en": "Fire Rate", "whole": false, "prefix": {"frag": "Croni", "cut": "[c]h[ron]os(+i)", "word": "χρόνος", "lang": "希腊语", "gloss": "时间", "rating": "2", "links": [{"label": "χρόνος", "url": "https://en.wiktionary.org/wiki/%CF%87%CF%81%CF%8C%CE%BD%CE%BF%CF%82#Ancient_Greek"}, {"label": "time → χρόνος", "url": "https://glosbe.com/en/grc/time"}], "why": "chronos 是「时间」，射速就是单位时间打几发。", "whyEn": "chronos means \"time\"; fire rate is shots per unit of time."}, "suffix": {"frag": "dra", "cut": "klepsý{dra}", "word": "κλεψύδρα", "lang": "希腊语", "gloss": "水钟", "rating": "1", "links": [{"label": "κλεψύδρα", "url": "https://en.wiktionary.org/wiki/κλεψύδρα#Ancient_Greek"}, {"label": "clepsydra", "url": "https://en.wiktionary.org/wiki/clepsydra#Latin"}, {"label": "water clock → clepsydra（拉丁语）", "url": "https://glosbe.com/en/la/water%20clock", "labelEn": "water clock → clepsydra (Latin)"}], "why": "klepsýdra 是古代计时用的「水钟」，取结尾。射速就是单位时间打几发，水钟就是计这个时间的，和 Croni 的「时间」说的是同一件事。", "whyEn": "klepsýdra is the ancient \"water clock\"; the end is taken. Fire rate is shots per unit of time, and a water clock measures that time: the same idea as Croni."}, "status": "active"}, {"id": "hexa-dex", "zh": "触发几率", "en": "Status Chance", "whole": false, "prefix": {"frag": "Hexa", "cut": "[hex](+a)", "word": "hex", "lang": "英语", "gloss": "诅咒", "rating": "1", "links": [{"label": "hex", "url": "https://en.wiktionary.org/wiki/hex#English"}], "why": "hex 是「诅咒」，触发异常状态就像给敌人下咒。", "whyEn": "hex means \"curse\": landing a status effect is like putting a curse on the enemy."}, "suffix": {"frag": "dex", "cut": "{dex}teritās", "word": "dexteritās", "lang": "拉丁语", "gloss": "灵巧", "rating": "2", "links": [{"label": "dexteritas", "url": "https://en.wiktionary.org/wiki/dexteritas#Latin"}, {"label": "Rifle Aptitude", "url": "https://wiki.warframe.com/w/Rifle_Aptitude"}, {"label": "Shotgun Savvy", "url": "https://wiki.warframe.com/w/Shotgun_Savvy"}, {"label": "dexterity → dexteritas", "url": "https://glosbe.com/en/la/dexterity"}], "why": "dexteritās 是「灵巧、才能」。触发几率 mod 正好叫 Rifle Aptitude（步枪才能），德语版叫 Begabung（天赋）；法语版 Shotgun Savvy 叫 Habile du Canon，habile 就是「灵巧」。", "whyEn": "dexteritās means \"skill, aptness\". The status chance mod is literally Rifle Aptitude, called Begabung (\"talent\") in German; in French, Shotgun Savvy is Habile du Canon, and habile means \"skilful\"."}, "status": "active"}, {"id": "deci-des", "zh": "触发时间", "en": "Status Duration", "whole": false, "prefix": {"frag": "Deci", "cut": "[deci]duous", "word": "deciduous", "lang": "英语", "gloss": "短暂、会消逝的", "rating": "1", "links": [{"label": "deciduous", "url": "https://en.wiktionary.org/wiki/deciduous#English"}], "why": "deciduous 除了「落叶的」，也有「短暂、不持久、会消逝」的意思，取开头。异常状态就是维持一阵、然后消退；不过它说的是「短暂」，不是「延长」。", "whyEn": "Besides \"leaf-shedding\", deciduous also means \"short-lived, transitory\"; the start is taken. A status effect lasts a while and then wears off, though the word says \"short-lived\", not \"longer\"."}, "suffix": {"frag": "des", "cut": "{dēs}iduō", "word": "dēsīduō", "lang": "拉丁语", "gloss": "长久", "rating": "2", "links": [{"label": "Fulgentius 第 37 条", "url": "https://www.thelatinlibrary.com/fulgentius/fulgentius4.shtml", "labelEn": "Fulgentius, entry 37"}, {"label": "Continuous Misery", "url": "https://wiki.warframe.com/w/Continuous_Misery"}, {"label": "Lingering Torment", "url": "https://wiki.warframe.com/w/Lingering_Torment"}, {"label": "Lasting Sting", "url": "https://wiki.warframe.com/w/Lasting_Sting"}, {"label": "a long time → desiduo", "url": "https://glosbe.com/en/la/a%20long%20time"}], "why": "dēsīduō 是「长久」，取开头 des，正好对应异常状态持续得更久。用英语 a long time 反查拉丁语，给出的就是 desiduo。同属性的 mod 叫 Continuous Misery（无尽苦难）、Lingering Torment（恒久折磨）、Lasting Sting（未完之刺），都在说「持久」。", "whyEn": "dēsīduō means \"for a long time\"; the start des is taken, matching statuses that last longer. Look up \"a long time\" in an English→Latin dictionary and desiduo is the answer. The same-stat mods are Continuous Misery, Lingering Torment and Lasting Sting: all about lasting."}, "status": "active"}, {"id": "igni-pha", "zh": "火焰伤害", "en": "Heat", "whole": false, "prefix": {"frag": "Igni", "cut": "[igni]s", "word": "ignis", "lang": "拉丁语", "gloss": "火", "rating": "3", "links": [{"label": "ignis", "url": "https://en.wiktionary.org/wiki/ignis#Latin"}, {"label": "fire → ignis", "url": "https://glosbe.com/en/la/fire"}], "why": "ignis 就是「火」，英语 ignite（点燃）也来自它。", "whyEn": "ignis simply means \"fire\"; English ignite comes from it."}, "suffix": {"frag": "pha", "cut": "{pha}os", "word": "φάος", "lang": "希腊语", "gloss": "光、火光", "rating": "1", "links": [{"label": "φάος", "url": "https://en.wiktionary.org/wiki/%CF%86%CE%AC%CE%BF%CF%82#Ancient_Greek"}, {"label": "Blaze", "url": "https://wiki.warframe.com/w/Blaze"}, {"label": "light → φῶς", "url": "https://glosbe.com/en/grc/light"}], "why": "phaos 是「光、火光」（常见的缩约形是 φῶς），取开头。火焰 mod Blaze 的西班牙语名是 Resplandor（光芒）。", "alts": [{"word": "φανός", "lang": "希腊语", "cut": "{pha}nós", "gloss": "火炬", "why": "phanós 是「火炬」，同样取开头。英文搜 Greek word for torch，结果里就有 φανός。", "links": [{"label": "φανός", "url": "https://en.wiktionary.org/wiki/φανός#Ancient_Greek"}, {"label": "φανός（Strong 词典 5322）", "url": "https://openbible.com/strongs/greek/5322.htm", "labelEn": "φανός (Strong's 5322)"}], "whyEn": "phanós means \"torch\"; again the start is taken. Search \"Greek word for torch\" and φανός comes up."}], "whyEn": "pháos means \"light, firelight\" (usually contracted to φῶς); the start is taken. The heat mod Blaze is called Resplandor (\"glow\") in Spanish."}, "status": "active"}, {"id": "geli-do", "zh": "冰冻伤害", "en": "Cold", "whole": true, "prefix": {"frag": "Geli", "cut": "[geli]{do}", "word": "gelido", "lang": "意大利语", "gloss": "冰冷的", "rating": "3", "links": [{"label": "gelido", "url": "https://en.wiktionary.org/wiki/gelido#Italian"}, {"label": "icy → gelido", "url": "https://glosbe.com/en/it/icy"}], "why": "gelido 是「冰冷的」，首尾各取一段。意式冰淇淋 gelato 也是这个词根。", "alts": [{"word": "gélido", "lang": "西班牙语", "cut": "[géli]{do}", "gloss": "冰冷的", "why": "西班牙语也是 gélido「冰冷的」。霰弹枪冰冻 mod Frigid Blast 的西语名就是 Explosión gélida，用的正是这个词。", "links": [{"label": "gélido", "url": "https://en.wiktionary.org/wiki/gélido#Spanish"}, {"label": "Frigid Blast", "url": "https://wiki.warframe.com/w/Frigid_Blast"}, {"label": "gelid → gélido", "url": "https://glosbe.com/en/es/gelid"}], "whyEn": "Spanish has gélido \"icy\" too, and the shotgun cold mod Frigid Blast is Explosión gélida in Spanish: the very same word."}], "whyEn": "gelido means \"icy\"; head and tail. Italian gelato shares the root."}, "suffix": {"frag": "do", "rating": "3", "links": []}, "status": "active"}, {"id": "vexi-tio", "zh": "电击伤害", "en": "Electricity", "whole": true, "prefix": {"frag": "Vexi", "cut": "[vex](+i)ā{tiō}", "word": "vexātiō", "lang": "拉丁语", "gloss": "剧烈摇晃", "rating": "3", "links": [{"label": "vexatio", "url": "https://en.wiktionary.org/wiki/vexatio#Latin"}, {"label": "Convulsion", "url": "https://wiki.warframe.com/w/Convulsion"}, {"label": "Jolt", "url": "https://wiki.warframe.com/w/Jolt"}, {"label": "shaking → vexatio", "url": "https://glosbe.com/en/la/shaking"}], "why": "vexātiō 是「剧烈摇晃」，像触电。电击 mod 就叫 Convulsion（痉挛）、Jolt（电流震击）。", "whyEn": "vexātiō means \"violent shaking\", like an electric shock. The electricity mods are Convulsion and Jolt."}, "suffix": {"frag": "tio", "rating": "3", "links": []}, "status": "active"}, {"id": "toxi-tox", "zh": "毒素伤害", "en": "Toxin", "whole": false, "prefix": {"frag": "Toxi", "cut": "[toxi]c", "word": "toxic", "lang": "英语", "gloss": "有毒的", "rating": "3", "links": [{"label": "toxicum", "url": "https://en.wiktionary.org/wiki/toxicum#Latin"}, {"label": "Toxic Barrage", "url": "https://wiki.warframe.com/w/Toxic_Barrage"}], "why": "toxic 是「有毒的」，取开头。游戏里也有 Toxic Barrage（毒素弹幕）这样直接叫 Toxic 的 mod。", "whyEn": "The start of toxic. Some mods are simply called Toxic, such as Toxic Barrage."}, "suffix": {"frag": "tox", "cut": "{tox}icum", "word": "toxicum", "lang": "拉丁语", "gloss": "毒药", "rating": "3", "links": [{"label": "toxicum", "url": "https://en.wiktionary.org/wiki/toxicum#Latin"}, {"label": "poison → toxicum", "url": "https://glosbe.com/en/la/poison"}], "why": "toxicum 是「毒药」，取开头。", "whyEn": "toxicum means \"poison\"; the start is taken."}, "status": "active"}, {"id": "sci-sus", "zh": "切割伤害", "en": "Slash", "whole": true, "prefix": {"frag": "Sci", "cut": "[sci]s{sus}", "word": "scissus", "lang": "拉丁语", "gloss": "撕裂的", "rating": "3", "links": [{"label": "scissus", "url": "https://en.wiktionary.org/wiki/scissus#Latin"}, {"label": "Rending Strike", "url": "https://wiki.warframe.com/w/Rending_Strike"}, {"label": "split → scindo", "url": "https://glosbe.com/en/la/split"}], "why": "scissus 是 scindō「劈开」的过去分词，「被劈开的」，取头尾、略去一个 s。切割 mod 有 Rending Strike（撕裂打击）。", "alts": [{"word": "scie", "lang": "法语", "cut": "[sci]e", "gloss": "锯", "why": "只能解释 Sci：步枪切割 mod Sawtooth Clip 的法语名 Chargeur en Dents de Scie 里有 scie「锯」。", "links": [{"label": "scie", "url": "https://en.wiktionary.org/wiki/scie#French"}, {"label": "Sawtooth Clip", "url": "https://wiki.warframe.com/w/Sawtooth_Clip"}, {"label": "saw → scie", "url": "https://glosbe.com/en/fr/saw"}], "whyEn": "Only explains Sci: the rifle slash mod Sawtooth Clip is Chargeur en Dents de Scie in French, with scie \"saw\"."}], "whyEn": "scissus is the past participle of scindō \"to split\": \"split apart\"; head and tail, dropping one s. One slash mod is Rending Strike."}, "suffix": {"frag": "sus", "rating": "3", "links": []}, "status": "active"}, {"id": "insi-cak", "zh": "穿刺伤害", "en": "Puncture", "whole": false, "prefix": {"frag": "Insi", "cut": "[īns]ecō(+i)", "word": "īnsecō", "lang": "拉丁语", "gloss": "切入", "rating": "2", "links": [{"label": "inseco", "url": "https://en.wiktionary.org/wiki/inseco#Latin"}, {"label": "Piercing Hit", "url": "https://wiki.warframe.com/w/Piercing_Hit"}, {"label": "cut into → inseco", "url": "https://glosbe.com/en/la/cut%20into"}], "why": "īnsecō 是「切入」，和穿刺的扎进去相近。穿刺 mod 就叫 Piercing Hit（穿甲伤害）。", "whyEn": "īnsecō means \"to cut into\", close to a puncture going in. The puncture mod is Piercing Hit."}, "suffix": {"frag": "cak", "cut": "{çak}mak", "word": "çakmak", "lang": "土耳其语", "gloss": "钉入", "rating": "1", "links": [{"label": "çakmak", "url": "https://en.wiktionary.org/wiki/%C3%A7akmak#Turkish"}, {"label": "drive in → çakmak", "url": "https://glosbe.com/en/tr/drive%20in"}], "why": "çakmak 是「敲进去、钉进去」，取开头。穿刺就像把钉子敲进去。", "whyEn": "çakmak means \"to drive in, to hammer in (a nail)\"; the start is taken. A puncture is like driving in a nail."}, "status": "active"}, {"id": "magna-ton", "zh": "冲击伤害", "en": "Impact", "whole": false, "prefix": {"frag": "Magna", "cut": "[magna]", "word": "magna", "lang": "拉丁语", "gloss": "巨大", "rating": "2", "links": [{"label": "magnus", "url": "https://en.wiktionary.org/wiki/magnus#Latin"}, {"label": "great → magnus", "url": "https://glosbe.com/en/la/great"}], "why": "magnus「巨大」的阴性 magna，冲击就是大力一砸。", "whyEn": "magna is the feminine of magnus \"great\": impact is a great, heavy smash."}, "suffix": {"frag": "ton", "cut": "{ton}", "word": "ton", "lang": "英语", "gloss": "吨", "rating": "1", "links": [{"label": "ton", "url": "https://en.wiktionary.org/wiki/ton#English"}, {"label": "Heavy Trauma", "url": "https://wiki.warframe.com/w/Heavy_Trauma"}], "why": "ton 是「吨」，和 Magna 连起来是「大吨位」。冲击 mod 叫 Heavy Trauma（重创）。", "whyEn": "ton as in the weight: with Magna, \"great tonnage\". The impact mod is Heavy Trauma."}, "status": "active"}, {"id": "argi-con", "zh": "对 Grineer 的伤害", "en": "Damage to Grineer", "whole": false, "prefix": {"frag": "Argi", "cut": "[argi]lla", "word": "argilla", "lang": "拉丁语", "gloss": "陶土", "rating": "1", "links": [{"label": "argilla", "url": "https://en.wiktionary.org/wiki/argilla#Latin"}, {"label": "clay → argilla", "url": "https://glosbe.com/en/la/clay"}], "why": "argilla 是「陶土」，意大利语也是 argilla，葡萄牙语是 argila。和后缀 εἰκών「像」连起来就是「陶土像」：一个模子压出一批一模一样的陶像，就像一批批复制出来的 Grineer。游戏里没说是黏土，这一半是联想。", "whyEn": "argilla means \"potter's clay\"; Italian also says argilla, Portuguese argila. With the suffix εἰκών \"likeness\" the pair reads \"clay figure\": one mould pressing out identical figures, like batch after batch of Grineer copies. The game never mentions clay, so this half is an association.", "alts": [{"word": "αργιλικών", "lang": "现代希腊语", "cut": "[argi]li{kon}", "gloss": "黏土的", "links": [{"label": "αργιλικός", "url": "https://en.wiktionary.org/wiki/%CE%B1%CF%81%CE%B3%CE%B9%CE%BB%CE%B9%CE%BA%CF%8C%CF%82#Greek"}], "why": "也可以整个词首尾各取：现代希腊语 argilikón「黏土的」，取 argi 和 kon。不过这里的 kon 只是形容词词尾，本身没有意思。", "whyEn": "Or both halves from one word: Modern Greek argilikón \"of clay\", taking argi and kon. But that kon is just an adjective ending with no meaning of its own."}]}, "suffix": {"frag": "con", "cut": "ei{kōn}", "word": "εἰκών", "lang": "希腊语", "gloss": "像、肖像", "rating": "2", "links": [{"label": "εἰκών", "url": "https://en.wiktionary.org/wiki/%CE%B5%E1%BC%B0%CE%BA%CF%8E%CE%BD#Ancient_Greek"}, {"label": "εἰκών（LSJ）", "labelEn": "εἰκών (LSJ)", "url": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.04.0057%3Aentry%3Dei%29kw%2Fn"}, {"label": "εἰκών（Strong 词典 1504）", "labelEn": "εἰκών (Strong's 1504)", "url": "https://biblehub.com/strongs/new/greek/1504.htm"}, {"label": "Grineer", "url": "https://wiki.warframe.com/w/Grineer"}], "why": "εἰκών 是「像、肖像」（LSJ 词典：likeness, image），英语 icon 就来自它，取结尾 kōn，k 写成 c。Grineer 正是复制品：平野指挥官的介绍写 A copy of a copy of a copy（作为复制体的复制的复制），帕尔沃斯的姐妹也说它们是 Copies of copies of copies of a real person（真人的复制体的复制体的复制体），法典写 Grineer are all clones from a genetic pool of ‘Originals’（全体皆是由「原始基因」的基因库复制生产而来）。英文搜 Greek word for likeness，结果里就有 εἰκών。", "whyEn": "εἰκών means \"likeness, image\" (LSJ), and English icon comes from it; the end kōn is taken, k written as c. The Grineer are exactly that, copies: the Plains Commander description says \"A copy of a copy of a copy\", a Sister of Parvos calls them \"Copies of copies of copies of a real person\", and the codex says they \"are all clones from a genetic pool of 'Originals'\". Search \"Greek word for likeness\" and εἰκών comes up."}, "status": "active"}, {"id": "manti-tron", "zh": "对 Corpus 的伤害", "en": "Damage to Corpus", "whole": false, "prefix": {"frag": "Manti", "cut": "[manti]cula", "word": "manticula", "lang": "拉丁语", "gloss": "小钱袋", "rating": "2", "links": [{"label": "manticula", "url": "https://en.wiktionary.org/wiki/manticula#Latin"}, {"label": "manticula（L&S）", "url": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.04.0059%3Aentry%3Dmanticula", "labelEn": "manticula (L&S)"}, {"label": "mantica", "url": "https://en.wiktionary.org/wiki/mantica#Latin"}, {"label": "Corpus", "url": "https://wiki.warframe.com/w/Corpus"}], "why": "manticula 是「小钱袋」，是 mantica「行囊」的小号，Lewis & Short 词典的释义是 a small wallet, purse, pouch。Corpus 的法典写着 the Corpus are dedicated to the accumulation of wealth（致力于累积财富），被七人众定罪为 a merchant cult（商业邪教），钱袋正对得上。", "alts": [], "whyEn": "manticula is a \"small purse\", the diminutive of mantica \"knapsack\"; Lewis & Short gives \"a small wallet, purse, pouch\". The Corpus codex says \"the Corpus are dedicated to the accumulation of wealth\", and the Seven condemned them as \"a merchant cult\": a purse fits."}, "suffix": {"frag": "tron", "cut": "-{tron}", "word": "-tron", "lang": "希腊语", "gloss": "器具", "rating": "1", "links": [{"label": "-tron", "url": "https://en.wiktionary.org/wiki/-tron#English"}, {"label": "-τρον（希腊语词尾）", "url": "https://en.wiktionary.org/wiki/-%CF%84%CF%81%CE%BF%CE%BD", "labelEn": "-τρον (Greek suffix)"}], "why": "词尾 -tron 常用来给器械起名，比如 cyclotron 回旋加速器。同一条法典写 Corpus 用 humans and robotics for labour and security（人类与机器人提供劳力与安全防护），恐鸟（MOA）这类机器人就是他们的兵。合起来就是「钱袋 + 机器」。英文搜 Greek suffix that forms names of tools，答案就是 -τρον。", "whyEn": "The ending -tron names instruments, as in cyclotron. The same codex says the Corpus use \"humans and robotics for labour and security\", and robots like MOAs are their soldiers. Together: purse + machine. Search \"Greek suffix that forms names of tools\" and the answer is -τρον."}, "status": "active"}, {"id": "pura-ada", "zh": "对 Infested 的伤害", "en": "Damage to Infested", "whole": false, "prefix": {"frag": "Pura", "cut": "[pura]", "word": "pura", "lang": "拉丁语", "gloss": "纯净", "rating": "3", "links": [{"label": "purus", "url": "https://en.wiktionary.org/wiki/purus#Latin"}, {"label": "Cleanse Infested", "url": "https://wiki.warframe.com/w/Cleanse_Infested"}, {"label": "pure → purus", "url": "https://glosbe.com/en/la/pure"}], "why": "pura 是「纯净」。对付 Infested 的 mod 就叫 Cleanse（净化）。", "whyEn": "pura means \"pure\". The anti-Infested mods are literally called Cleanse."}, "suffix": {"frag": "ada", "cut": "purg{ada}", "word": "purgada", "lang": "西班牙语", "gloss": "被净化的", "rating": "2", "links": [{"label": "purgar", "url": "https://en.wiktionary.org/wiki/purgar#Spanish"}, {"label": "purge → purgar", "url": "https://glosbe.com/en/es/purge"}], "why": "purgada 是 purgar「净化」的过去分词，「被净化的」，取结尾；-ada 很常见，只是可能。", "whyEn": "purgada is the past participle of purgar \"to purge\": \"purged\"; the end is taken. -ada is a very common ending, so this is only a maybe."}, "status": "active"}, {"id": "arma-tin", "zh": "弹匣容量", "en": "Magazine Capacity", "whole": false, "prefix": {"frag": "Arma", "cut": "[arma]", "word": "arma", "lang": "拉丁语", "gloss": "武器", "rating": "2", "links": [{"label": "arma", "url": "https://en.wiktionary.org/wiki/arma#Latin"}, {"label": "weapons → arma", "url": "https://glosbe.com/en/la/weapons"}], "why": "arma 是「武器」。弹匣的英文 magazine 本义是「仓库」，军事上专指「弹药库」；拉丁语里存放武器的军械库叫 armāmentārium，开头就是 arma。武器的库房，正好就是弹匣。", "alts": [{"word": "armāmentārium", "lang": "拉丁语", "cut": "[arma]mentārium", "gloss": "军械库", "why": "armāmentārium 就是「军械库」，取开头。和 magazine 的「弹药库」是同一个意思。", "links": [{"label": "armamentarium", "url": "https://en.wiktionary.org/wiki/armamentarium#Latin"}, {"label": "magazine（词源：仓库、弹药库）", "url": "https://en.wiktionary.org/wiki/magazine#English", "labelEn": "magazine (etymology: storehouse)"}, {"label": "arsenal → armamentarium", "url": "https://glosbe.com/en/la/arsenal"}], "whyEn": "armāmentārium is an \"armoury\"; the start is taken. The same idea as magazine's \"ammunition store\"."}], "whyEn": "arma means \"weapons\". The English magazine originally meant a \"storehouse\", and in the army an ammunition store; Latin for an armoury is armāmentārium, which starts with arma. A store for weapons is exactly a magazine."}, "suffix": {"frag": "tin", "cut": "{tin}", "word": "tin", "lang": "英语", "gloss": "金属罐", "rating": "1", "links": [{"label": "tin", "url": "https://en.wiktionary.org/wiki/tin#English"}], "why": "tin 是「铁皮罐、铁皮盒」，装东西的金属容器。弹匣就是装子弹的铁盒子；英式英语里弹药盒也常叫 ammo tin。", "alts": [{"word": "contineō", "lang": "拉丁语", "cut": "con{tin}eō", "gloss": "容纳、装得下", "why": "contineō 是「容纳、装得下」，中间正好是 tin，英语 contain 就来自它。弹匣容量就是弹匣装得下多少。不过要取词中间的字母，比较少见。", "links": [{"label": "contineo", "url": "https://en.wiktionary.org/wiki/contineo#Latin"}, {"label": "contain → continere", "url": "https://glosbe.com/en/la/contain"}], "whyEn": "contineō means \"to hold, contain\", with tin in the middle; English contain comes from it. Magazine capacity is how much the magazine holds. Taking letters from the middle of a word is rare, though."}], "whyEn": "tin as in a tin box: a metal container. A magazine is a metal box of bullets, and in British English an ammo box is often an ammo tin."}, "status": "active"}, {"id": "ampi-bin", "zh": "弹药最大值", "en": "Ammo Maximum", "whole": false, "prefix": {"frag": "Ampi", "cut": "[ampi]", "word": "ampi", "lang": "意大利语", "gloss": "充裕", "rating": "2", "links": [{"label": "ampio", "url": "https://en.wiktionary.org/wiki/ampio#Italian"}, {"label": "ample → ampio", "url": "https://glosbe.com/en/it/ample"}], "why": "ampi 是「宽大、充裕」，弹药带得多。", "whyEn": "ampi means \"wide, ample\": carrying plenty of ammo."}, "suffix": {"frag": "bin", "cut": "{bin}", "word": "bin", "lang": "英语", "gloss": "储物箱", "rating": "1", "links": [{"label": "bin", "url": "https://en.wiktionary.org/wiki/bin#English"}, {"label": "Ammo Drum", "url": "https://wiki.warframe.com/w/Ammo_Drum"}], "why": "bin 是「储物箱」，存弹药的地方。弹药最大值 mod 叫 Ammo Drum（弹鼓），也是容器。", "whyEn": "bin as in a storage bin, where the ammo is kept. The ammo maximum mod is Ammo Drum, also a container."}, "status": "active"}, {"id": "feva-tak", "zh": "装填速度", "en": "Reload Speed", "whole": false, "prefix": {"frag": "Feva", "cut": "[fev]er(+a)", "word": "fever", "lang": "英语", "gloss": "发热、狂热", "rating": "1", "links": [{"label": "fever", "url": "https://en.wiktionary.org/wiki/fever#English"}, {"label": "Seeking Fury", "url": "https://wiki.warframe.com/w/Seeking_Fury"}, {"label": "The Vincentian：feva (fever)", "url": "https://thevincentian.com/flow-catches-the-feva-p8564-94.htm", "labelEn": "The Vincentian: feva (fever)"}], "why": "fever 是「发热、狂热」。英式口音不念结尾的 r，读起来就是「菲娃」，像 nok（knock）一样按读音拼；2015 年圣文森特的报纸 The Vincentian 就写过 'feva' (fever)。装填加速的 Seeking Fury、Combo Fury 都带 Fury（狂暴）。", "alts": [], "whyEn": "fever: \"heat, frenzy\". In a non-rhotic accent the final r is silent, so it sounds like \"fee-vuh\", spelled by sound like nok for knock; a 2015 newspaper from St Vincent, The Vincentian, literally writes 'feva' (fever). The reload mods Seeking Fury and Combo Fury both have Fury in the name."}, "suffix": {"frag": "tak", "cut": "{tak}tisch", "word": "taktisch", "lang": "德语", "gloss": "战术", "rating": "2", "links": [{"label": "taktisch", "url": "https://en.wiktionary.org/wiki/taktisch#German"}, {"label": "Tactical Pump", "url": "https://wiki.warframe.com/w/Tactical_Pump"}, {"label": "tactical → taktisch", "url": "https://glosbe.com/en/de/tactical"}], "why": "taktisch 是「战术的」。装填速度 mod Tactical Pump（战术上膛）的德语名就是 Taktisches Laden。", "alts": [{"word": "ταχύς", "lang": "希腊语", "cut": "", "gloss": "快", "why": "tachýs 是「快」，ch 念 k，开头读音就是 tak（英语 tachometer 转速表也来自它）。", "links": [{"label": "ταχύς", "url": "https://en.wiktionary.org/wiki/ταχύς#Ancient_Greek"}, {"label": "fast → ταχύς", "url": "https://glosbe.com/en/grc/fast"}], "whyEn": "tachýs means \"fast\"; ch is said as k, so it starts with the sound tak (English tachometer comes from it)."}, {"word": "takmak", "lang": "土耳其语", "cut": "{tak}mak", "gloss": "装上", "why": "takmak 是「装上、接上」，取开头。土耳其枪厂 Sarsılmaz 的手枪说明书写 Şarjörü çıkartıp tekrar takınız（取出弹匣，重新装上），装弹匣用的就是它。", "links": [{"label": "takmak", "url": "https://en.wiktionary.org/wiki/takmak"}, {"label": "Sarsılmaz 手枪说明书 第 34 页", "url": "https://www.sarsilmaz.com/public/uploads/en-1741091741.pdf#page=34", "labelEn": "Sarsılmaz pistol manual, p. 34"}, {"label": "attach → takmak", "url": "https://glosbe.com/en/tr/attach"}], "whyEn": "takmak means \"to attach, to fit\"; the start is taken. The Turkish manual of a Sarsılmaz pistol says \"Şarjörü çıkartıp tekrar takınız\" (take the magazine out and insert it again): the very word for putting a magazine in."}], "whyEn": "taktisch means \"tactical\". The reload speed mod Tactical Pump is Taktisches Laden in German."}, "status": "active"}, {"id": "zeti-mag", "zh": "武器后坐力", "en": "Weapon Recoil", "whole": false, "prefix": {"frag": "Zeti", "cut": "[zet]a(+i)", "word": "zeta", "lang": "希腊字母", "gloss": "阻尼比 ζ", "rating": "1", "links": [{"label": "zeta", "url": "https://en.wiktionary.org/wiki/zeta#English"}, {"label": "Wikipedia：阻尼比 ζ", "url": "https://en.wikipedia.org/wiki/Damping#Damping_ratio", "labelEn": "Wikipedia: damping ratio ζ"}, {"label": "Stabilizer", "url": "https://wiki.warframe.com/w/Stabilizer"}, {"label": "Counterbalance", "url": "https://wiki.warframe.com/w/Counterbalance"}], "why": "zeta（ζ）在工程上表示「阻尼比」，减后坐和减震是一个思路。后坐力 mod 叫 Stabilizer（稳定）、Counterbalance（制衡）。", "whyEn": "zeta (ζ) is the engineering symbol for the damping ratio, and reducing recoil is a kind of damping. The recoil mods are Stabilizer and Counterbalance."}, "suffix": {"frag": "mag", "cut": "{mag}netic", "word": "magnetic", "lang": "英语", "gloss": "磁阻尼", "rating": "1", "links": [{"label": "Wikipedia：磁阻尼", "url": "https://en.wikipedia.org/wiki/Damping#Magnetic_damping", "labelEn": "Wikipedia: magnetic damping"}, {"label": "Ahmadian & Poynor 2001：磁流变阻尼器控制枪械后坐", "url": "https://doi.org/10.1155/2001/674830", "labelEn": "Ahmadian & Poynor 2001: MR dampers for gun recoil"}], "why": "magnetic 是「磁」。2001 年的论文 An Evaluation of Magneto Rheological Dampers for Controlling Gun Recoil Dynamics（Shock and Vibration 期刊）研究的就是用磁流变阻尼器控制枪的后坐。和 Zeti 的阻尼比 ζ 连起来，整对就是「用磁阻尼压住后坐」。", "alts": [{"word": "Magnum Force", "lang": "英语（mod 名）", "cut": "{Mag}num", "gloss": "麦格农", "why": "手枪 mod Magnum Force 内部名叫 CorruptedDamageRecoil，最早是「加伤害、加后坐力」的腐化 mod；magnum 子弹也以后坐力大出名。", "links": [{"label": "Magnum Force", "url": "https://wiki.warframe.com/w/Magnum_Force"}], "whyEn": "The pistol mod Magnum Force is internally CorruptedDamageRecoil: it started as a corrupted mod giving more damage and more recoil, and magnum rounds are known for heavy recoil."}], "whyEn": "magnetic. A 2001 paper, An Evaluation of Magneto Rheological Dampers for Controlling Gun Recoil Dynamics (Shock and Vibration), studies exactly this: controlling gun recoil with magnetorheological dampers. With Zeti's damping ratio ζ, the pair reads \"magnetic damping to hold recoil down\"."}, "status": "active"}, {"id": "hera-lis", "zh": "变焦", "en": "Zoom", "whole": false, "prefix": {"frag": "Hera", "cut": "[h]i[era]x", "word": "ἱέραξ", "lang": "希腊语", "gloss": "鹰隼", "rating": "2", "links": [{"label": "ἱέραξ", "url": "https://en.wiktionary.org/wiki/%E1%BC%B1%CE%AD%CF%81%CE%B1%CE%BE#Ancient_Greek"}, {"label": "Hawk Eye", "url": "https://wiki.warframe.com/w/Hawk_Eye"}, {"label": "hawk → ἱέραξ", "url": "https://glosbe.com/en/grc/hawk"}], "why": "hiérāx 是「鹰隼」，去掉 i 和 x。手枪的变焦 mod 就叫 Hawk Eye（隼目）。", "whyEn": "hiérāx means \"hawk\", dropping the i and the x. The pistol zoom mod is Hawk Eye."}, "suffix": {"frag": "lis", "cut": "ocu{līs}", "word": "oculīs", "lang": "拉丁语", "gloss": "用眼睛", "rating": "1", "links": [{"label": "oculis", "url": "https://en.wiktionary.org/wiki/oculis#Latin"}, {"label": "Hawk Eye", "url": "https://wiki.warframe.com/w/Hawk_Eye"}, {"label": "Eagle Eye", "url": "https://wiki.warframe.com/w/Eagle_Eye"}, {"label": "eye → oculus", "url": "https://glosbe.com/en/la/eye"}], "why": "oculīs 是 oculus「眼睛」的复数夺格，意思是「用眼睛」，取结尾：鹰 + 眼，正好是变焦 mod 的名字，步枪的叫 Eagle Eye（鹰眼），手枪的叫 Hawk Eye（隼目）。", "whyEn": "oculīs is the ablative plural of oculus \"eye\": \"with the eyes\"; the end is taken. Hawk + eyes is exactly what the zoom mods are called: Eagle Eye for rifles, Hawk Eye for pistols."}, "status": "active"}, {"id": "conci-nak", "zh": "投射物速度", "en": "Projectile Speed", "whole": false, "prefix": {"frag": "Conci", "cut": "[conci]tus", "word": "concitus", "lang": "拉丁语", "gloss": "急速", "rating": "2", "links": [{"label": "concitus", "url": "https://en.wiktionary.org/wiki/concitus#Latin"}, {"label": "Terminal Velocity", "url": "https://wiki.warframe.com/w/Terminal_Velocity"}, {"label": "Fatal Acceleration", "url": "https://wiki.warframe.com/w/Fatal_Acceleration"}, {"label": "roused → concitus", "url": "https://glosbe.com/en/la/roused"}], "why": "concitus 是「急速的」，子弹飞得快。投射物速度 mod 叫 Terminal Velocity（极限速度）、Fatal Acceleration（致死加速）。", "whyEn": "concitus means \"rapid, roused\": a fast bullet. The projectile speed mods are Terminal Velocity and Fatal Acceleration."}, "suffix": {"frag": "nak", "cut": "{nak}ata", "word": "nakata", "lang": "芬兰语", "gloss": "投掷", "rating": "1", "links": [{"label": "nakata", "url": "https://en.wiktionary.org/wiki/nakata#Finnish"}, {"label": "throw → nakata", "url": "https://glosbe.com/en/fi/throw"}], "why": "nakata 是「扔、抛」，取开头。投射物就是被扔出去的东西，和 Conci 的「急速」合起来就是「扔得快」。", "whyEn": "nakata means \"to throw\"; the start is taken. A projectile is something thrown, and with Conci's \"rapid\" it reads \"thrown fast\"."}, "status": "active"}, {"id": "lexi-nok", "zh": "穿透", "en": "Punch Through", "whole": false, "prefix": {"frag": "Lexi", "cut": "p[lēxi]s", "word": "πλῆξις", "lang": "希腊语", "gloss": "一击", "rating": "1", "links": [{"label": "πλῆξις", "url": "https://en.wiktionary.org/wiki/%CF%80%CE%BB%E1%BF%86%CE%BE%CE%B9%CF%82#Ancient_Greek"}, {"label": "πλήσσω（Strong 词典 4141）", "url": "https://biblehub.com/greek/4141.htm", "labelEn": "πλήσσω (Strong's 4141)"}], "why": "穿透英文叫 Punch Through，plēxis 就是「一击」，取中间的 lexi。英文搜 ancient Greek word for a blow，会搜到动词 πλήσσω「打」，plēxis 就是它的名词。", "whyEn": "The stat is Punch Through, and plēxis means \"a blow\"; the middle, lexi, is taken. Search \"ancient Greek word for a blow\" and you get the verb πλήσσω \"to strike\", of which plēxis is the noun."}, "suffix": {"frag": "nok", "cut": "k{no}c{k}", "word": "knock", "lang": "英语", "gloss": "敲击", "rating": "1", "links": [{"label": "Cambridge: knock through", "url": "https://dictionary.cambridge.org/dictionary/english/knock-through"}], "why": "knock 是「敲」，按读音写成 nok；knock through 就是「打通墙」。", "whyEn": "knock, spelled by sound as nok; to knock through is to break through a wall."}, "status": "active"}, {"id": "tempi-nem", "zh": "连击持续时间", "en": "Combo Duration", "whole": false, "prefix": {"frag": "Tempi", "cut": "[tempi]", "word": "tempi", "lang": "意大利语", "gloss": "时间", "rating": "2", "links": [{"label": "tempo", "url": "https://en.wiktionary.org/wiki/tempo#Italian"}, {"label": "time → tempo", "url": "https://glosbe.com/en/it/time"}], "why": "tempi 是 tempo「时间」的复数。", "whyEn": "tempi is the plural of tempo \"time\"."}, "suffix": {"frag": "nem", "cut": "dūrātiō{nem}", "word": "dūrātiōnem", "lang": "中世纪拉丁语", "gloss": "持续", "rating": "2", "links": [{"label": "duratio", "url": "https://en.wiktionary.org/wiki/duratio#Latin"}, {"label": "duration → duratio", "url": "https://glosbe.com/en/la/duration"}], "why": "dūrātiōnem（dūrātiō「持续」的宾格），取结尾。时间 + 持续 = 连击持续时间。", "whyEn": "dūrātiōnem is the accusative of dūrātiō \"duration\"; the end is taken. Time + duration = combo duration."}, "status": "active"}, {"id": "pleci-nent", "zh": "滑行攻击暴击几率", "en": "Critical Chance for Slide Attack", "whole": false, "prefix": {"frag": "Pleci", "cut": "[plēc]tō(+i)", "word": "plēctō", "lang": "拉丁语", "gloss": "击打", "rating": "2", "links": [{"label": "plecto", "url": "https://en.wiktionary.org/wiki/plecto#Latin"}, {"label": "Maiming Strike", "url": "https://wiki.warframe.com/w/Maiming_Strike"}, {"label": "punish → plectere", "url": "https://glosbe.com/en/la/punish"}], "why": "plēctō 是「击打」。滑行暴击 mod 叫 Maiming Strike（致残突击）。", "whyEn": "plēctō means \"to strike\". The slide crit mod is Maiming Strike."}, "suffix": {"frag": "nent", "cut": "{nent}", "word": "nent", "lang": "拉丁语", "gloss": "旋转", "rating": "2", "links": [{"label": "neo", "url": "https://en.wiktionary.org/wiki/neo#Latin"}, {"label": "nent", "url": "https://en.wiktionary.org/wiki/nent#Latin"}, {"label": "spin → neo", "url": "https://glosbe.com/en/la/spin"}], "why": "nent 是「他们在纺线」（neō 的变位），英文释义 to spin。游戏里 Excalibur、Baruuk 的技巧提示把滑行攻击叫作 Spin Attack（旋转攻击），这是 spin 的双关。", "whyEn": "nent means \"they spin (thread)\", a form of neō, glossed in English as to spin. In-game tips for Excalibur and Baruuk call slide attacks \"Spin Attack\": a pun on spin."}, "status": "active"}, {"id": "locti-tor", "zh": "攻击范围", "en": "Range", "whole": false, "prefix": {"frag": "Locti", "cut": "[loc]ā[ti]ō", "word": "locātiō", "lang": "拉丁语", "gloss": "放置、位置", "rating": "1", "links": [{"label": "locatio", "url": "https://en.wiktionary.org/wiki/locatio#Latin"}, {"label": "locus", "url": "https://en.wiktionary.org/wiki/locus#Latin"}, {"label": "Reach", "url": "https://wiki.warframe.com/w/Reach"}, {"label": "locō（locāre）", "url": "https://en.wiktionary.org/wiki/loco#Latin", "labelEn": "locō (locāre)"}], "why": "locātiō 本义是「放置」，词根 loc- 就是「地方、位置」（locus），英语 location 也来自它；能打到的位置就是攻击范围。要跳过中间的 a。攻击范围 mod 叫 Reach（剑风）。英文搜 Latin word for placing，会搜到 locāre「放置」，locātiō 是它的名词。", "whyEn": "locātiō originally means \"placing\", and its root loc- means \"place\" (locus), as in English location; the places you can reach are your range. The a in the middle has to be skipped. The range mod is Reach. Search \"Latin word for placing\" and you get locāre \"to place\", of which locātiō is the noun."}, "suffix": {"frag": "tor", "cut": "{tor}nos", "word": "τόρνος", "lang": "希腊语", "gloss": "画圆的工具；圆", "rating": "1", "links": [{"label": "τόρνος（LSJ 希腊语词典）", "url": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.04.0057:entry=to/rnos", "labelEn": "τόρνος (LSJ)"}, {"label": "τόρνος", "url": "https://en.wiktionary.org/wiki/%CF%84%CF%8C%CF%81%CE%BD%CE%BF%CF%82#Ancient_Greek"}], "why": "tórnos 是木匠用来画圆的工具，像圆规，也指「圆」，取开头。近战武器以你为中心挥出去，能打到的就是这样一圈。英语 turn（转）也来自这个词。英文搜 Greek word for compass used to draw a circle，就能搜到 τόρνος。", "alts": [{"word": "sector", "lang": "英语", "cut": "sec{tor}", "gloss": "扇形", "why": "sector 在几何上是「扇形」：两条半径加一段圆弧。挥一刀扫过的就是一块扇形，攻击范围决定它有多大。取结尾。", "links": [{"label": "sector", "url": "https://en.wiktionary.org/wiki/sector#English"}], "whyEn": "In geometry a sector is two radii plus an arc. One sweep of a blade covers a sector, and range decides how big it is. The end is taken."}], "whyEn": "tórnos is a carpenter's tool for drawing circles, like a compass, and also \"circle\"; the start is taken. A melee swing around you covers such a circle. English turn comes from it. Search \"Greek word for compass used to draw a circle\" and τόρνος comes up."}, "status": "active"}, {"id": "exi-cta", "zh": "处决伤害", "en": "Finisher Damage", "whole": true, "prefix": {"frag": "Exi", "cut": "[ex](+i)stīn{cta}", "word": "exstīncta", "lang": "拉丁语", "gloss": "被熄灭、被杀死的", "rating": "3", "links": [{"label": "exstinctus", "url": "https://en.wiktionary.org/wiki/exstinctus#Latin"}, {"label": "exseco（另一路线：切除）", "url": "https://en.wiktionary.org/wiki/exseco#Latin", "labelEn": "exseco (another route: to cut out)"}, {"label": "Covert Lethality", "url": "https://wiki.warframe.com/w/Covert_Lethality"}, {"label": "Finishing Touch", "url": "https://wiki.warframe.com/w/Finishing_Touch"}, {"label": "extinct → Exstinctus", "url": "https://glosbe.com/en/la/extinct"}], "why": "exstīncta 是「被熄灭、被杀死的」，前缀取开头 ex 补个 i，后缀取结尾 cta。处决 mod 叫 Covert Lethality（致命匿杀）、Finishing Touch（画龙点睛）。", "whyEn": "exstīncta means \"extinguished, killed\"; the prefix is the start ex plus an added i, the suffix is the end cta. The finisher mods are Covert Lethality and Finishing Touch."}, "suffix": {"frag": "cta", "rating": "3", "links": []}, "status": "active"}, {"id": "forti-us", "zh": "重击效率", "en": "Heavy Attack Efficiency", "whole": true, "prefix": {"frag": "Forti", "cut": "[forti]{us}", "word": "fortius", "lang": "拉丁语", "gloss": "更有力地", "rating": "3", "links": [{"label": "fortius", "url": "https://en.wiktionary.org/wiki/fortius#Latin"}, {"label": "fortis", "url": "https://en.wiktionary.org/wiki/fortis#Latin"}, {"label": "bravely → fortiter", "url": "https://glosbe.com/en/la/bravely"}], "why": "fortius 是 fortiter「有力地」的比较级，「更有力地」，重击就是用力打。", "whyEn": "fortius is the comparative of fortiter \"strongly\": \"more strongly\". A heavy attack is hitting hard."}, "suffix": {"frag": "us", "rating": "3", "links": []}, "status": "active"}, {"id": "para-um", "zh": "初始连击", "en": "Initial Combo", "whole": true, "prefix": {"frag": "Para", "cut": "[parā]t{um}", "word": "parātum", "lang": "拉丁语", "gloss": "准备好的", "rating": "3", "links": [{"label": "paratus", "url": "https://en.wiktionary.org/wiki/paratus#Latin"}, {"label": "Ready Steel", "url": "https://wiki.warframe.com/w/Ready_Steel"}, {"label": "ready → paratus", "url": "https://glosbe.com/en/la/ready"}], "why": "parātum 是 parātus「准备好的」的中性形式，初始连击就是一开始就备好了。mod Ready Steel 的 ready 也是「准备好」。", "whyEn": "parātum is the neuter of parātus \"prepared\": an initial combo is a combo that's ready from the start. The mod Ready Steel says ready too."}, "suffix": {"frag": "um", "rating": "3", "links": []}, "status": "active"}, {"id": "laci-nus", "zh": "额外连击数几率", "en": "Additional Combo Count Chance", "whole": false, "prefix": {"frag": "Laci", "cut": "[lac]essō(+i)", "word": "lacessō", "lang": "拉丁语", "gloss": "挑衅", "rating": "1", "links": [{"label": "lacesso", "url": "https://en.wiktionary.org/wiki/lacesso#Latin"}, {"label": "Guardian Derision", "url": "https://wiki.warframe.com/w/Guardian_Derision"}, {"label": "provoke → lacesso", "url": "https://glosbe.com/en/la/provoke"}], "why": "lacessō 是「挑衅、进攻」。同属性的 Guardian Derision（奚落守护）描述写着 Blocking taunts enemies（格挡会嘲讽敌人），西班牙语版就叫 Provocación del guardián（守护者的挑衅）。", "whyEn": "lacessō means \"to provoke, attack\". The same-stat mod Guardian Derision says \"Blocking taunts enemies\", and its Spanish name is Provocación del guardián (\"the guardian's provocation\")."}, "suffix": {"frag": "nus", "cut": "bo{nus}", "word": "bonus", "lang": "英语", "gloss": "额外奖励", "rating": "2", "links": [{"label": "bonus", "url": "https://en.wiktionary.org/wiki/bonus#English"}], "why": "bonus 是「额外奖励」，额外连击就是有机会多算连击。", "whyEn": "bonus: \"an extra reward\". Additional combo count chance is a chance to count extra combo hits."}, "status": "active"}, {"id": "cali-fel", "zh": "毒气伤害", "en": "Gas", "whole": false, "prefix": {"frag": "Cali", "cut": "[cālī]gō", "word": "cālīgō", "lang": "拉丁语", "gloss": "浓雾", "rating": "2", "links": [{"label": "caligo", "url": "https://en.wiktionary.org/wiki/caligo#Latin"}, {"label": "mist → caligo", "url": "https://glosbe.com/en/la/mist"}], "why": "cālīgō 是「浓雾」，毒气是一团雾。", "whyEn": "cālīgō means \"thick mist\": gas is a cloud."}, "suffix": {"frag": "fel", "cut": "{fel}", "word": "fel", "lang": "拉丁语", "gloss": "毒液", "rating": "2", "links": [{"label": "fel", "url": "https://en.wiktionary.org/wiki/fel#Latin"}, {"label": "venom → fel", "url": "https://glosbe.com/en/la/venom"}], "why": "fel 是「毒液」。雾 + 毒 = 毒气。", "whyEn": "fel means \"venom\". Mist + venom = gas."}, "status": "active"}, {"id": "cori-or", "zh": "腐蚀伤害", "en": "Corrosive", "whole": true, "prefix": {"frag": "Cori", "cut": "[cor](+i)rōd{or}", "word": "corrōdor", "lang": "拉丁语", "gloss": "被腐蚀", "rating": "3", "links": [{"label": "corrodo", "url": "https://en.wiktionary.org/wiki/corrodo#Latin"}, {"label": "gnaw away → corrodo", "url": "https://glosbe.com/en/la/gnaw%20away"}], "why": "corrōdor 是 corrōdō「腐蚀」的被动式，「被腐蚀」，英语 corrode 同源。", "whyEn": "corrōdor is the passive of corrōdō \"to gnaw away\": \"I am corroded\". English corrode shares the root."}, "suffix": {"frag": "or", "rating": "3", "links": []}, "status": "active"}, {"id": "cari-sco", "zh": "病毒伤害", "en": "Viral", "whole": false, "prefix": {"frag": "Cari", "cut": "[cari]ēs", "word": "cariēs", "lang": "拉丁语", "gloss": "腐烂", "rating": "2", "links": [{"label": "caries", "url": "https://en.wiktionary.org/wiki/caries#Latin"}, {"label": "decay → caries", "url": "https://glosbe.com/en/la/decay"}], "why": "cariēs 是「腐烂」，借疾病、腐坏的意象。", "whyEn": "cariēs means \"decay\", borrowing the image of disease and rot."}, "suffix": {"frag": "sco", "cut": "putrē{scō}", "word": "putrēscō", "lang": "拉丁语", "gloss": "腐朽", "rating": "1", "links": [{"label": "putresco", "url": "https://en.wiktionary.org/wiki/putresco#Latin"}, {"label": "putrefy → putresco", "url": "https://glosbe.com/en/la/putrefy"}], "why": "putrēscō 是「腐朽」，取结尾。和 Cari 的「腐烂」一样，借病毒让身体腐坏的意象。", "whyEn": "putrēscō means \"to rot\"; the end is taken. Like Cari's \"decay\", it's the image of a virus rotting the body."}, "status": "active"}, {"id": "radi-lo", "zh": "辐射伤害", "en": "Radiation", "whole": false, "prefix": {"frag": "Radi", "cut": "[radi]us", "word": "radius", "lang": "拉丁语", "gloss": "光线", "rating": "3", "links": [{"label": "radius", "url": "https://en.wiktionary.org/wiki/radius#Latin"}, {"label": "ray → radius", "url": "https://glosbe.com/en/la/ray"}], "why": "radius 是「光线」，英语 radiation（辐射）同源。", "whyEn": "radius means \"ray\"; English radiation shares the root."}, "suffix": {"frag": "lo", "cut": "radiar{lo}", "word": "radiarlo", "lang": "西班牙语", "gloss": "辐射它", "rating": "1", "links": [{"label": "radiar", "url": "https://en.wiktionary.org/wiki/radiar#Spanish"}, {"label": "irradiate → radiar", "url": "https://glosbe.com/en/es/irradiate"}], "why": "radiarlo 是「辐射它」（radiar 辐射 + lo 它），取结尾。lo 本身只是「它」，所以只是可能。", "whyEn": "radiarlo means \"to irradiate it\" (radiar + lo \"it\"); the end is taken. lo on its own is just \"it\", so this is only a maybe."}, "status": "active"}, {"id": "fraga-tus", "zh": "爆炸伤害", "en": "Blast", "whole": false, "prefix": {"frag": "Fraga", "cut": "[frag]or(+a)", "word": "fragor", "lang": "拉丁语", "gloss": "碎裂声", "rating": "2", "links": [{"label": "fragor", "url": "https://en.wiktionary.org/wiki/fragor#Latin"}, {"label": "crash → fragor", "url": "https://glosbe.com/en/la/crash"}], "why": "fragor 是「碎裂的巨响」，很适合形容爆炸。", "whyEn": "fragor means \"a crash, the noise of breaking\": a good word for an explosion."}, "suffix": {"frag": "tus", "cut": "frāc{tus}", "word": "frāctus", "lang": "拉丁语", "gloss": "被打碎的", "rating": "2", "links": [{"label": "fractus", "url": "https://en.wiktionary.org/wiki/fractus#Latin"}, {"label": "frangō", "url": "https://en.wiktionary.org/wiki/frango"}], "why": "frāctus 是「被打碎的」，取结尾。英文搜 Latin word for broken，会搜到 frangere「打碎」，frāctus 就是它的过去分词。", "whyEn": "frāctus means \"broken\"; the end is taken. Search \"Latin word for broken\" and you get frangere \"to break\", of which frāctus is the past participle."}, "status": "active"}, {"id": "magni-bra", "zh": "磁力伤害", "en": "Magnetic", "whole": false, "prefix": {"frag": "Magni", "cut": "[magn]ēs(+i)", "word": "magnēs", "lang": "拉丁语", "gloss": "磁石", "rating": "2", "links": [{"label": "magnes", "url": "https://en.wiktionary.org/wiki/magnes#Latin"}, {"label": "magnet → magnes", "url": "https://glosbe.com/en/la/magnet"}], "why": "magnēs 是「磁石」，英语 magnet 同源。", "whyEn": "magnēs means \"magnet\"; English magnet shares the root."}, "suffix": {"frag": "bra", "cut": "illece{bra}", "word": "illecebra", "lang": "拉丁语", "gloss": "吸引物", "rating": "2", "links": [{"label": "illecebra", "url": "https://en.wiktionary.org/wiki/illecebra#Latin"}, {"label": "Mag", "url": "https://wiki.warframe.com/w/Mag"}, {"label": "Magnetic Might", "url": "https://wiki.warframe.com/w/Magnetic_Might"}, {"label": "allurement → illecebra", "url": "https://glosbe.com/en/la/allurement"}], "why": "illecebra 是「吸引人的东西」。手枪磁力 mod Magnetic Might 的中文名叫「磁吸巨力」；Mag 的介绍写着 Few can resist her attraction or her repulsion（几乎无人能抵挡她的吸引力或排斥力）。", "whyEn": "illecebra means \"an attraction, a lure\". Mag's description says \"Few can resist her attraction or her repulsion.\" In Simplified Chinese the pistol magnetic mod Magnetic Might is called 磁吸巨力, \"magnetic pull, great force\"."}, "status": "active"}, {"id": "effi-tas", "zh": "对奥罗金的伤害", "en": "Damage to Orokin", "whole": true, "prefix": {"frag": "Effi", "cut": "[eff](+i)eri{tās}", "word": "efferitās", "lang": "拉丁语", "gloss": "野蛮、堕落", "rating": "2", "links": [{"label": "efferitas", "url": "https://en.wiktionary.org/wiki/efferitas#Latin"}, {"label": "wildness → efferitas", "url": "https://glosbe.com/en/la/wildness"}], "why": "efferitās 是「野蛮、堕落」，前缀取开头 eff 补个 i。这条打的是 Corrupted（堕落者），也就是被奥罗金塔控制、腐化的敌人，游戏内部就把这条属性叫 FactionDamageCorrupted。", "alts": [{"word": "effigiēs + immortālitās", "lang": "拉丁语", "cut": "", "gloss": "塑像 + 不朽", "why": "另一种猜法：effigiēs「塑像」取开头、immortālitās「不朽」取结尾，对应奥罗金的雕像和永生。", "links": [{"label": "effigies", "url": "https://en.wiktionary.org/wiki/effigies#Latin"}, {"label": "immortalitas", "url": "https://en.wiktionary.org/wiki/immortalitas#Latin"}, {"label": "statue → effigies", "url": "https://glosbe.com/en/la/statue"}, {"label": "immortality → immortalitas", "url": "https://glosbe.com/en/la/immortality"}], "whyEn": "Another guess: the start of effigiēs \"statue\" and the end of immortālitās \"immortality\", for the Orokin's statues and eternal life."}], "whyEn": "efferitās means \"savagery, degeneracy\"; the prefix is the start eff plus an added i. This stat hits the Corrupted, enemies taken over by the Orokin towers, and the game internally calls it FactionDamageCorrupted."}, "suffix": {"frag": "tas", "rating": "2", "links": []}, "status": "active"}, {"id": "muti-gia", "zh": "对科腐者的伤害", "en": "Damage to Techrot", "whole": false, "prefix": {"frag": "Muti", "cut": "[muti]", "word": "muti", "lang": "意大利语", "gloss": "改变", "rating": "2", "links": [{"label": "mutare", "url": "https://en.wiktionary.org/wiki/mutare#Italian"}, {"label": "Techrot", "url": "https://wiki.warframe.com/w/Techrot"}, {"label": "change → mutare", "url": "https://glosbe.com/en/it/change"}], "why": "mutare 是「改变」，muti 是它的变位。Lettie 的短信里说 the Techrot strain had mutated（科腐者病毒株已经变异）。", "alts": [{"word": "mūtātiō", "lang": "拉丁语", "cut": "[mūt](+i)ātiō", "gloss": "改变、突变", "why": "mūtātiō 是「改变」，取开头 mūt 补个 i。", "links": [{"label": "mutatio", "url": "https://en.wiktionary.org/wiki/mutatio#Latin"}, {"label": "mutation → mutatio", "url": "https://glosbe.com/en/la/mutation"}], "whyEn": "mūtātiō means \"change\"; the start mūt plus an added i."}], "whyEn": "mutare means \"to change\", and muti is one of its forms. Lettie's message says \"the Techrot strain had mutated\"."}, "suffix": {"frag": "gia", "cut": "tecnolo{gia}", "word": "tecnologia", "lang": "意大利语", "gloss": "科技", "rating": "2", "links": [{"label": "tecnologia", "url": "https://en.wiktionary.org/wiki/tecnologia#Italian"}, {"label": "technology → tecnologia", "url": "https://glosbe.com/en/it/technology"}], "why": "tecnologia 是「科技」，取结尾。1999 任务的广播说 Techrot. A virus both biological and electronic（科腐者。这是一种生物性与电子性并存的病毒）：变异 + 科技 = 科技腐化。", "whyEn": "tecnologia means \"technology\"; the end is taken. The 1999 broadcast says \"Techrot. A virus both biological and electronic\": mutation + technology."}, "status": "active"}, {"id": "exsi-llo", "zh": "对炽蛇军的伤害", "en": "Damage to Scaldra", "whole": true, "prefix": {"frag": "Exsi", "cut": "[exs](+i)tī{llō}", "word": "exstīllō", "lang": "拉丁语", "gloss": "一滴滴流出", "rating": "2", "links": [{"label": "exstillo", "url": "https://en.wiktionary.org/wiki/exstillo#Latin"}, {"label": "Scaldra", "url": "https://wiki.warframe.com/w/Scaldra"}, {"label": "trickle away → exstillo", "url": "https://glosbe.com/en/la/trickle%20away"}], "why": "exstīllō 是「一滴滴流出」，前缀取开头 exs 补个 i，后缀取结尾 llō。时装秘炼师制服（Chymerist Uniform）的描述写着 Scaldra’s secret Efervon distilleries（炽蛇军的秘密艾弗旺蒸馏厂）。", "whyEn": "exstīllō means \"to trickle out drop by drop\"; the prefix is the start exs plus an added i, the suffix is the end llō. The Chymerist Uniform description mentions \"Scaldra's secret Efervon distilleries\"."}, "suffix": {"frag": "llo", "rating": "2", "links": []}, "status": "active"}, {"id": "eni-vo", "zh": "弱点伤害", "en": "Weak Point Damage", "whole": true, "prefix": {"frag": "Eni", "cut": "[ēn](+i)er{vō}", "word": "ēnervō", "lang": "拉丁语", "gloss": "削弱", "rating": "3", "links": [{"label": "enervo", "url": "https://en.wiktionary.org/wiki/enervo#Latin"}, {"label": "weaken → enervo", "url": "https://glosbe.com/en/la/weaken"}], "why": "ēnervō 是「削弱」，能呼应 Weak Point（弱点）的「弱」。", "whyEn": "ēnervō means \"to weaken\", echoing the \"weak\" in Weak Point."}, "suffix": {"frag": "vo", "rating": "3", "links": []}, "status": "active"}, {"id": "exiti-eus", "zh": "弱点暴击几率", "en": "Weak Point Critical Chance", "whole": false, "prefix": {"frag": "Exiti", "cut": "[exiti]um", "word": "exitium", "lang": "拉丁语", "gloss": "毁灭", "rating": "2", "links": [{"label": "exitium", "url": "https://en.wiktionary.org/wiki/exitium#Latin"}, {"label": "destruction → exitium", "url": "https://glosbe.com/en/la/destruction"}], "why": "exitium 是「毁灭」。这是熔接属性「弱点暴击几率」，名字对着的是后半的「暴击几率」：暴击就是致命的一下。", "whyEn": "exitium means \"destruction\". This spliced trait is Weak Point Critical Chance, and the name follows its main stat, critical chance: a crit is the deadly hit."}, "suffix": {"frag": "eus", "cut": "fūner{eus}", "word": "fūnereus", "lang": "拉丁语", "gloss": "致命的", "rating": "2", "links": [{"label": "funereus", "url": "https://en.wiktionary.org/wiki/funereus#Latin"}, {"label": "funereal → funereus", "url": "https://glosbe.com/en/la/funereal"}, {"label": "Deadly Sequence", "url": "https://wiki.warframe.com/w/Deadly_Sequence"}], "why": "fūnereus 是「致命的」，取结尾，英语 funeral（葬礼）同源。暴击几率 mod 里就有一张 Deadly Sequence（致命数列），deadly 正是「致命的」；步枪暴击 mod Point Strike 的中文名也叫「致命一击」（这是中文译名，英文原名里没有「致命」）。", "whyEn": "fūnereus means \"deadly\"; the end is taken. English funeral shares the root. One crit chance mod is literally Deadly Sequence. In Simplified Chinese the rifle crit mod Point Strike is called 致命一击, \"deadly strike\", but that's only the translation; the English name has no \"deadly\"."}, "status": "active"}, {"id": "plaga-mna", "zh": "异常状态伤害", "en": "Status Damage", "whole": false, "prefix": {"frag": "Plaga", "cut": "[plaga]", "word": "plāga", "lang": "拉丁语", "gloss": "打击、创伤", "rating": "2", "links": [{"label": "plaga", "url": "https://en.wiktionary.org/wiki/plaga#Latin"}, {"label": "wound → plaga", "url": "https://glosbe.com/en/la/wound"}], "why": "plāga 是「打击、创伤」，英语 plague（瘟疫）同源。这是熔接属性「异常状态伤害」，plāga 和后缀的 damna 都在说「伤害」。", "whyEn": "plāga means \"blow, wound\"; English plague shares the root. This spliced trait is Status Damage, and both plāga and the suffix's damna say \"damage\"."}, "suffix": {"frag": "mna", "cut": "da{mna}", "word": "damna", "lang": "拉丁语", "gloss": "损害", "rating": "2", "links": [{"label": "damnum", "url": "https://en.wiktionary.org/wiki/damnum#Latin"}, {"label": "loss → damnum", "url": "https://glosbe.com/en/la/loss"}, {"label": "damage（词源）", "url": "https://en.wiktionary.org/wiki/damage", "labelEn": "damage (etymology)"}], "why": "damna（damnum「损害」的复数），取结尾。英语 damage（伤害）就是从 damnum 来的，正好就是属性名里的 Damage。", "whyEn": "damna is the plural of damnum \"loss, harm\"; the end is taken. English damage comes from damnum: it's literally the Damage in the stat name."}, "status": "active"}, {"id": "parci-pia", "zh": "弹药效率", "en": "Ammo Efficiency", "whole": false, "prefix": {"frag": "Parci", "cut": "[parci]", "word": "parcī", "lang": "拉丁语", "gloss": "节省的", "rating": "2", "links": [{"label": "parcus", "url": "https://en.wiktionary.org/wiki/parcus#Latin"}, {"label": "thrifty → parcus", "url": "https://glosbe.com/en/la/thrifty"}], "why": "parcus「节省的」的变格 parcī，弹药效率就是省子弹。", "whyEn": "parcī is a form of parcus \"sparing\": ammo efficiency is saving bullets."}, "suffix": {"frag": "pia", "cut": "cō{pia}", "word": "cōpia", "lang": "拉丁语", "gloss": "储备", "rating": "1", "links": [{"label": "copia", "url": "https://en.wiktionary.org/wiki/copia#Latin"}, {"label": "abundance → copia", "url": "https://glosbe.com/en/la/abundance"}], "why": "cōpia 是「储备、补给」，取结尾。省着用（parcī），储备（cōpia）就撑得更久，这就是弹药效率。", "whyEn": "cōpia means \"supply, stock\"; the end is taken. Spend sparingly (parcī) and the supply (cōpia) lasts longer: that's ammo efficiency."}, "status": "active"}, {"id": "auxi-rro", "zh": "收起时自动装填", "en": "Holster Reload", "whole": false, "prefix": {"frag": "Auxi", "cut": "[auxi]lium", "word": "auxilium", "lang": "拉丁语", "gloss": "帮助", "rating": "2", "links": [{"label": "auxilium", "url": "https://en.wiktionary.org/wiki/auxilium#Latin"}, {"label": "help → auxilium", "url": "https://glosbe.com/en/la/help"}], "why": "auxilium 是「帮助」。收起时自动装填，就像收起武器时有人帮你把子弹装好。", "whyEn": "auxilium means \"help\". Holster reload is like someone reloading your weapon for you while it's put away."}, "suffix": {"frag": "rro", "cut": "soco{rro}", "word": "socorro", "lang": "西班牙语", "gloss": "救援", "rating": "2", "links": [{"label": "socorro", "url": "https://en.wiktionary.org/wiki/socorro#Spanish"}, {"label": "relief → socorro", "url": "https://glosbe.com/en/es/relief"}], "why": "socorro 是「救援」，也指送去的补给、援军，取结尾。收起武器时给你补上弹药。", "whyEn": "socorro means \"rescue\", and also supplies or reinforcements sent in; the end is taken. Your ammo gets topped up while the weapon is holstered."}, "status": "dedicated", "shownAs": "Parci·pia"}, {"id": "robi-ndo", "zh": "重击时的近战伤害", "en": "Heavy Melee Damage", "whole": true, "prefix": {"frag": "Robi", "cut": "[rōb](+i)ora{ndō}", "word": "rōborandō", "lang": "拉丁语", "gloss": "加强", "rating": "2", "links": [{"label": "roboro", "url": "https://en.wiktionary.org/wiki/roboro#Latin"}, {"label": "strengthen → roboro", "url": "https://glosbe.com/en/la/strengthen"}], "why": "rōborandō 是「加强」，前缀取 rōb 补 i。重击更有力。", "whyEn": "rōborandō means \"by strengthening\"; the prefix is rōb plus an added i. A heavy attack hits harder."}, "suffix": {"frag": "ndo", "rating": "2", "links": []}, "status": "dedicated", "shownAs": "Laci·nus"}, {"id": "veri-lus", "zh": "重击准备速度", "en": "Heavy Attack Wind Up", "whole": true, "prefix": {"frag": "Veri", "cut": "[ver](+i)ticil{lus}", "word": "verticillus", "lang": "拉丁语", "gloss": "纺轮", "rating": "1", "links": [{"label": "verticillus", "url": "https://en.wiktionary.org/wiki/verticillus#Latin"}, {"label": "纺锤与纺轮（宾州州立大学展品说明）", "url": "https://exhibitions.psu.edu/s/flax/item/4957", "labelEn": "Spindles and whorls (Penn State exhibit)"}, {"label": "Swift Momentum", "url": "https://wiki.warframe.com/w/Swift_Momentum"}, {"label": "whorl → verticillus", "url": "https://glosbe.com/en/la/whorl"}], "why": "verticillus 是纺锤上的「纺轮」，博物馆说明写它 provide rotational momentum（提供旋转动量）；加重击准备速度的光环 mod 正好叫 Swift Momentum（迅敏动量）。英文 Wind Up 的 wind 本来也是「绕线」。前缀取开头 ver 补个 i，后缀取结尾 lus。", "whyEn": "verticillus is the whorl on a spindle; a museum note says whorls \"provide rotational momentum\", and the aura that speeds up heavy attack wind-up is Swift Momentum. The wind in Wind Up also originally means winding thread. The prefix is the start ver plus an added i, the suffix is the end lus."}, "suffix": {"frag": "lus", "rating": "1", "links": []}, "status": "dedicated", "shownAs": "Laci·nus"}, {"id": "defi-so", "zh": "招架角度", "en": "Parry Angle", "whole": true, "prefix": {"frag": "Defi", "cut": "[dēf](+i)ēn{sō}", "word": "dēfēnsō", "lang": "拉丁语", "gloss": "防守", "rating": "2", "links": [{"label": "defenso", "url": "https://en.wiktionary.org/wiki/defenso#Latin"}, {"label": "Focused Defense", "url": "https://wiki.warframe.com/w/Focused_Defense"}, {"label": "defend → defenso", "url": "https://glosbe.com/en/la/defend"}], "why": "dēfēnsō 是「防守、抵挡」，招架就是挡。加招架角度的 mod 正好叫 Focused Defense（重点防御）。", "whyEn": "dēfēnsō means \"to defend, ward off\": a parry is a block. The parry angle mod is Focused Defense."}, "suffix": {"frag": "so", "rating": "2", "links": []}, "status": "dedicated", "shownAs": "Laci·nus"}, {"id": "proci-lam", "zh": "震地攻击伤害", "en": "Slam Damage", "whole": false, "prefix": {"frag": "Proci", "cut": "[prōci]dō", "word": "prōcidō", "lang": "拉丁语", "gloss": "向前扑倒", "rating": "1", "links": [{"label": "procido", "url": "https://en.wiktionary.org/wiki/procido#Latin"}, {"label": "fall forward → procido", "url": "https://glosbe.com/en/la/fall%20forward"}], "why": "prōcidō 是「向前扑倒、倒下」，开头正好是 proci，像震地时整个人砸下去。", "alts": [{"word": "procellam", "lang": "拉丁语", "cut": "[proc](+i)ellam", "gloss": "风暴、冲击", "why": "procella「风暴、冲击」的宾格，要补 i。", "links": [{"label": "procella", "url": "https://en.wiktionary.org/wiki/procella#Latin"}, {"label": "storm → procella", "url": "https://glosbe.com/en/la/storm"}], "whyEn": "The accusative of procella \"storm, onslaught\"; needs an added i."}], "whyEn": "prōcidō means \"to fall forward, fall down\", and it starts exactly with proci, like your whole body crashing down in a slam."}, "suffix": {"frag": "lam", "cut": "s{lam}", "word": "slam", "lang": "英语", "gloss": "猛砸", "rating": "2", "links": [{"label": "slam", "url": "https://en.wiktionary.org/wiki/slam#English"}, {"label": "lam（英语：痛打）", "url": "https://en.wiktionary.org/wiki/lam#English", "labelEn": "lam (English: to thrash)"}], "why": "slam（猛砸）的结尾，震地攻击的英文就是 Slam Attack；英语 lam 本身也是「狠揍」。", "whyEn": "The end of slam, and the attack is called Slam Attack; lam on its own also means \"to thrash\"."}, "status": "dedicated", "shownAs": "Laci·nus"}, {"id": "prola-go", "zh": "光束长度", "en": "Beam Length", "whole": true, "prefix": {"frag": "Prola", "cut": "[prol](+a)on{gō}", "word": "prolongō", "lang": "拉丁语", "gloss": "延长", "rating": "3", "links": [{"label": "prolongo", "url": "https://en.wiktionary.org/wiki/prolongo#Latin"}, {"label": "Sinister Reach", "url": "https://wiki.warframe.com/w/Sinister_Reach"}, {"label": "Ruinous Extension", "url": "https://wiki.warframe.com/w/Ruinous_Extension"}, {"label": "prolong → prolongo", "url": "https://glosbe.com/en/la/prolong"}], "why": "prolongō 是「延长」，英语 prolong 同源。加光束长度的 mod 叫 Sinister Reach（凶恶延伸），手枪版 Ruinous Extension 的法语名就是 Prolongement Ruineux。", "whyEn": "prolongō means \"to lengthen\"; English prolong shares the root. The beam length mod is Sinister Reach, and the pistol one, Ruinous Extension, is Prolongement Ruineux in French."}, "suffix": {"frag": "go", "rating": "3", "links": []}, "status": "reserved"}, {"id": "resi-nte", "zh": "弹跳", "en": "Bounce", "whole": true, "prefix": {"frag": "Resi", "cut": "[resi]lie{nte}", "word": "resiliente", "lang": "西班牙语", "gloss": "回弹的", "rating": "3", "links": [{"label": "resiliente", "url": "https://en.wiktionary.org/wiki/resiliente#Spanish"}, {"label": "Kinetic Ricochet", "url": "https://wiki.warframe.com/w/Kinetic_Ricochet"}, {"label": "resilient → resiliente", "url": "https://glosbe.com/en/es/resilient"}], "why": "resiliente 现在是「有韧性的」，来自拉丁语 resilīre「弹回」。弹跳 mod Kinetic Ricochet 的西语名叫 Rebote cinético。", "whyEn": "resiliente now means \"resilient\", from Latin resilīre \"to spring back\". The bounce mod Kinetic Ricochet is Rebote cinético in Spanish."}, "suffix": {"frag": "nte", "rating": "3", "links": []}, "status": "reserved"}, {"id": "ince-vus", "zh": "首发伤害", "en": "First Shot Damage", "whole": true, "prefix": {"frag": "Ince", "cut": "[ince]ptī{vus}", "word": "inceptīvus", "lang": "中世纪拉丁语", "gloss": "开始的", "rating": "3", "links": [{"label": "inceptivus", "url": "https://en.wiktionary.org/wiki/inceptivus#Latin"}], "why": "inceptīvus 是「开始的」，首发就是第一发。", "whyEn": "inceptīvus means \"of the beginning\": the first shot."}, "suffix": {"frag": "vus", "rating": "3", "links": []}, "status": "reserved"}, {"id": "perfri-era", "zh": "战刃穿透", "en": "Glaive Punch Through", "whole": false, "prefix": {"frag": "Perfri", "cut": "[perfri]ngō", "word": "perfringō", "lang": "拉丁语", "gloss": "击穿", "rating": "2", "links": [{"label": "perfringo", "url": "https://en.wiktionary.org/wiki/perfringo#Latin"}, {"label": "break through → perfringo", "url": "https://glosbe.com/en/la/break%20through"}], "why": "perfringō 是「击穿」。", "whyEn": "perfringō means \"to break through\"."}, "suffix": {"frag": "era", "cut": "p{era}", "word": "πέρα", "lang": "希腊语", "gloss": "越过", "rating": "1", "links": [{"label": "πέρα", "url": "https://en.wiktionary.org/wiki/πέρα"}, {"label": "πέρα（Strong 词典 4082）", "url": "https://biblehub.com/strongs/new/greek/4082.htm", "labelEn": "πέρα (Strong's 4082)"}], "why": "péra 是「越过」，去掉 p；πέρα ως πέρα 就是「从这头到那头、贯穿」。英文搜 Greek word for beyond，直接给出的就是 πέρα。", "whyEn": "péra means \"beyond\", dropping the p; πέρα ως πέρα means \"from end to end, right through\". Search \"Greek word for beyond\" and the answer is πέρα."}, "status": "reserved"}, {"id": "termi-pio", "zh": "爆头倍率", "en": "Headshot Multiplier", "whole": false, "prefix": {"frag": "Termi", "cut": "[termi]nus", "word": "terminus", "lang": "拉丁语", "gloss": "终点", "rating": "1", "links": [{"label": "terminus", "url": "https://en.wiktionary.org/wiki/terminus#Latin"}, {"label": "boundary → terminus", "url": "https://glosbe.com/en/la/boundary"}], "why": "terminus 是「终点」，借终结敌人的意象，比较弱。", "whyEn": "terminus means \"end\", borrowing the image of finishing the enemy off; fairly weak."}, "suffix": {"frag": "pio", "cut": "ca{piō}", "word": "capiō", "lang": "拉丁语", "gloss": "拿下", "rating": "1", "links": [{"label": "capio", "url": "https://en.wiktionary.org/wiki/capio#Latin"}, {"label": "Target Acquired", "url": "https://wiki.warframe.com/w/Target_Acquired"}, {"label": "seize → capere", "url": "https://glosbe.com/en/la/seize"}], "why": "capiō 是「拿到、捕获」。爆头 mod 叫 Target Acquired（锁定目标），acquire 就是「获得」，法语名 Cible Acquise 也一样。", "whyEn": "capiō means \"to take, to seize\". The headshot mod is Target Acquired, acquire meaning \"to get\"; the French name Cible Acquise says the same."}, "status": "reserved"}, {"id": "reci-cul", "zh": "狙击连击持续", "en": "Sniper Combo Duration", "whole": false, "prefix": {"frag": "Reci", "cut": "", "word": "", "lang": "", "gloss": "未知", "rating": "0", "links": [], "why": ""}, "suffix": {"frag": "cul", "cut": "", "word": "", "lang": "", "gloss": "未知", "rating": "0", "links": [], "why": ""}, "status": "reserved"}, {"id": "tori-bo", "zh": "引导伤害", "en": "Channeling Damage", "whole": false, "prefix": {"frag": "Tori", "cut": "[torī]", "word": "torī", "lang": "拉丁语", "gloss": "肌肉（复数）", "rating": "1", "links": [{"label": "torus", "url": "https://en.wiktionary.org/wiki/torus#Latin"}, {"label": "muscle → torus", "url": "https://glosbe.com/en/la/muscle"}], "why": "torus「肌肉」的复数正好是 torī，联想到近战的力量。", "whyEn": "torī is the plural of torus \"muscle\", suggesting melee strength."}, "suffix": {"frag": "bo", "cut": "", "word": "", "lang": "", "gloss": "未知", "rating": "0", "links": [], "why": ""}, "status": "removed"}, {"id": "uti-tia", "zh": "引导效率", "en": "Channeling Efficiency", "whole": false, "prefix": {"frag": "Uti", "cut": "[ūtī]", "word": "ūtī", "lang": "拉丁语", "gloss": "使用", "rating": "2", "links": [{"label": "utor", "url": "https://en.wiktionary.org/wiki/utor#Latin"}, {"label": "use → uti", "url": "https://glosbe.com/en/la/use"}], "why": "ūtī 是「使用」。", "whyEn": "ūtī means \"to use\"."}, "suffix": {"frag": "tia", "cut": "efficien{tia}", "word": "efficientia", "lang": "拉丁语", "gloss": "效能", "rating": "2", "links": [{"label": "efficientia", "url": "https://en.wiktionary.org/wiki/efficientia#Latin"}, {"label": "efficiency → efficientia", "url": "https://glosbe.com/en/la/efficiency"}], "why": "efficientia 是「效能」，取结尾。使用 + 效能 = 引导效率。", "whyEn": "efficientia means \"efficiency\"; the end is taken. Use + efficiency = channeling efficiency."}, "status": "removed"}]};
